{
 "app_name": "venmo",
 "api_name": "show_payment_cards",
 "path": "/payment_cards",
 "method": "GET",
 "description": "Get a list of users payment cards.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from venmo app login.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": [
   {
    "payment_card_id": 1,
    "card_name": "string",
    "owner_name": "string",
    "card_number": 1000000000000000.0,
    "expiry_year": 1,
    "expiry_month": 1.0,
    "cvv_number": 100.0
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}
